// 订阅型渠道的入账（§3.5，ratio_snapshot 恒为 1——§12 拍板）。
//
// **与 UpsertProfitDaily 的唯一区别，也是本片对 §5.1 的唯一偏离**：
// 收入侧未知时**照样建行**。理由记在 docs/modules/finance/README.md，一句话：
// §5.1 的「只有一侧就不建行」防的是「拿一次失败的读取拼出一行」，而订阅成本
// 不是读来的——它是我们自己付出去的钱按天摊开的算术，不存在读不到。
// 把它压住，平台自己承诺的支出会在收入通道接上之前完全不可见。
//
// 收入侧用 COALESCE 而不是直接覆盖：本轮读到就刷新，没读到就保留今天早些时候
// 已经读到的那个值——与 UpdateProfitDailyCost「一次失败的读取不该把另一侧
// 连带抹掉」是同一条纪律。observed_at 跟着值走，否则会出现「值是上一轮的、
// 时间戳是这一轮的」这种替陈旧数据背书的组合。
func (q *Queries) UpsertProfitDailyAmortizedCost(ctx context.Context, arg UpsertProfitDailyAmortizedCostParams) (FinanceProfitDaily, error) {
	row := q.db.QueryRow(ctx, upsertProfitDailyAmortizedCost,
		arg.UpstreamAccountID,
		arg.BusinessDay,
		arg.BusinessDayTz,
		arg.TokenID,
		arg.AccountID,
		arg.PlatformID,
		arg.RevenueMinor,
		arg.CostMinor,
		arg.Currency,
		arg.RatioSnapshot,
		arg.Source,
		arg.CostObservedAt,
		arg.RevenueObservedAt,
	)
	var i FinanceProfitDaily
	err := row.Scan(
		&i.UpstreamAccountID,
		&i.BusinessDay,
		&i.BusinessDayTz,
		&i.TokenID,
		&i.AccountID,
		&i.PlatformID,
		&i.RevenueMinor,
		&i.CostMinor,
		&i.ProfitMinor,
		&i.Currency,
		&i.RatioSnapshot,
		&i.Source,
		&i.CostObservedAt,
		&i.RevenueObservedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertTokenMapping = `-- name: UpsertTokenMapping :one
INSERT INTO finance.token_map (
    upstream_account_id, upstream_token_id, own_account_id, credential_ref,
    created_at, updated_at
) VALUES (
    $1, $2,
    $3, $4, now(), now()
)
ON CONFLICT (upstream_account_id, upstream_token_id) DO UPDATE SET
    own_account_id = EXCLUDED.own_account_id,
    credential_ref = EXCLUDED.credential_ref,
    updated_at     = now()
RETURNING upstream_account_id, upstream_token_id, own_account_id, credential_ref, created_at, updated_at
`

type UpsertTokenMappingParams struct {
	UpstreamAccountID uuid.UUID
	UpstreamTokenID   string
	OwnAccountID      string
	CredentialRef     *string
}

// 登记或改写一条令牌映射。
//
// ON CONFLICT DO UPDATE 而不是先查后写：映射是「这个上游令牌对应哪个自营
// 账号」的**当前事实**，重复登记同一个令牌就是在纠正它，不该报唯一冲突
// 让运营去猜要先删再加。
func (q *Queries) UpsertTokenMapping(ctx context.Context, arg UpsertTokenMappingParams) (FinanceTokenMap, error) {
	row := q.db.QueryRow(ctx, upsertTokenMapping,
		arg.UpstreamAccountID,
		arg.UpstreamTokenID,
		arg.OwnAccountID,
		arg.CredentialRef,
	)
	var i FinanceTokenMap
	err := row.Scan(
		&i.UpstreamAccountID,
		&i.UpstreamTokenID,
		&i.OwnAccountID,
		&i.CredentialRef,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
